// ConsumedAtGTE applies the GTE predicate on the "consumed_at" field.
func ConsumedAtGTE(v time.Time) predicate.AccountDeletionChallenge {
	return predicate.AccountDeletionChallenge(sql.FieldGTE(FieldConsumedAt, v))
}

